// ============================================================================
// PURO: reposo lejos de la boca -> beso (piquito) -> se acerca y suelta humo
// ============================================================================
// Ajustes (unidades de la escena del editor). Si quieres afinar la posicion,
// cambia solo estos tres valores:
//   REST_OFFSET : cuanto se aleja el puro de su posicion "en la boca" cuando NO hay beso.
//   KISS_OFFSET : ajuste fino de la posicion con beso (para que toque los labios).
//   TIP_LOCAL   : extremo encendido del puro (de donde sale el humo), en coordenadas del grupo.
const REST_OFFSET = new THREE.Vector3(-0.25, -0.75, 0.30);
const KISS_OFFSET = new THREE.Vector3(-0.07, 0.0, 0.10);
const TIP_LOCAL   = new THREE.Vector3(0.79, -0.512, 0.79);

const APPROACH_SPEED = 9;    // que tan rapido llega a la boca
const RETREAT_SPEED  = 5;    // que tan rapido se aleja al terminar el beso
const SMOKE_RATE     = 16;   // bocanadas por segundo mientras hay beso
const MAX_PARTICLES  = 48;

let basePos = new THREE.Vector3();   // posicion original del editor (en la boca)
let restPos = new THREE.Vector3();
let kissPos = new THREE.Vector3();
let kissing = false;
let progress = 0;                    // 0 = lejos, 1 = en la boca
let emitAcc = 0;

let smokeGroup = null;
let smokeTexture = null;
const particles = [];
const tmp = new THREE.Vector3();

function makeSmokeTexture() {
	const size = 64;
	const canvas = document.createElement('canvas');
	canvas.width = canvas.height = size;
	const ctx = canvas.getContext('2d');
	const g = ctx.createRadialGradient(size / 2, size / 2, 0, size / 2, size / 2, size / 2);
	g.addColorStop(0, 'rgba(255,255,255,0.9)');
	g.addColorStop(0.45, 'rgba(255,255,255,0.4)');
	g.addColorStop(1, 'rgba(255,255,255,0)');
	ctx.fillStyle = g;
	ctx.fillRect(0, 0, size, size);
	return new THREE.CanvasTexture(canvas);
}

function spawnParticle() {
	let p = particles.find((q) => !q.alive);
	if (!p) {
		if (particles.length >= MAX_PARTICLES) return;
		const material = new THREE.SpriteMaterial({
			map: smokeTexture, color: 0xe8e8e8, transparent: true,
			opacity: 0, depthWrite: false
		});
		const sprite = new THREE.Sprite(material);
		sprite.visible = false;
		smokeGroup.add(sprite);
		p = { sprite, vel: new THREE.Vector3(), alive: false, age: 0, life: 1, size0: 0.1, grow: 0.3, spin: 0 };
		particles.push(p);
	}

	// Punta del puro en el espacio del padre (Accesorios).
	this_updateTip();
	p.sprite.position.copy(tmp).add(new THREE.Vector3(
		(Math.random() - 0.5) * 0.03, (Math.random() - 0.5) * 0.02, (Math.random() - 0.5) * 0.03));
	p.vel.set((Math.random() - 0.5) * 0.10, 0.22 + Math.random() * 0.14, 0.02 + Math.random() * 0.05);
	p.age = 0;
	p.life = 1.6 + Math.random() * 1.0;
	p.size0 = 0.08 + Math.random() * 0.05;
	p.grow = 0.28 + Math.random() * 0.2;
	p.spin = (Math.random() - 0.5) * 0.8;
	p.sprite.material.rotation = Math.random() * Math.PI * 2;
	p.sprite.scale.setScalar(p.size0);
	p.sprite.material.opacity = 0;
	p.sprite.visible = true;
	p.alive = true;
}

let cigar = null;
function this_updateTip() {
	cigar.updateMatrix();
	tmp.copy(TIP_LOCAL).applyMatrix4(cigar.matrix);
}

function clearSmoke() {
	for (const p of particles) { p.alive = false; p.sprite.visible = false; }
}

// ---- Ciclo de vida -------------------------------------------------------

function start() {
	cigar = this;
	basePos.copy(this.position);
	restPos.copy(basePos).add(REST_OFFSET);
	kissPos.copy(basePos).add(KISS_OFFSET);
	kissing = false;
	progress = 0;
	emitAcc = 0;
	this.position.copy(restPos);   // arranca lejos de la boca

	smokeTexture = makeSmokeTexture();
	smokeGroup = new THREE.Group();
	smokeGroup.name = 'HumoPuro';
	if (this.parent) this.parent.add(smokeGroup);
}

function stop() {
	if (smokeGroup && smokeGroup.parent) smokeGroup.parent.remove(smokeGroup);
	for (const p of particles) p.sprite.material.dispose();
	particles.length = 0;
	if (smokeTexture) smokeTexture.dispose();
	smokeGroup = null;
	smokeTexture = null;
}

function update(event) {
	if (!smokeGroup) return;
	const dt = Math.min(event.delta / 1000, 0.05);

	// Acercar / alejar el puro con suavizado (independiente de los FPS).
	const target = kissing ? 1 : 0;
	const speed = kissing ? APPROACH_SPEED : RETREAT_SPEED;
	progress += (target - progress) * (1 - Math.exp(-speed * dt));
	if (Math.abs(target - progress) < 0.001) progress = target;

	this.position.lerpVectors(restPos, kissPos, progress);
	// Flotacion suave mientras esta en reposo.
	this.position.y += Math.sin(event.time / 600) * 0.015 * (1 - progress);

	// Humo: solo cuando el puro ya llego (casi) a la boca y sigue el beso.
	if (kissing && progress > 0.85) {
		emitAcc += SMOKE_RATE * dt;
		while (emitAcc >= 1) { emitAcc -= 1; spawnParticle(); }
	} else {
		emitAcc = 0;
	}

	// Animar particulas (las que ya salieron se desvanecen aunque el puro se aleje).
	for (const p of particles) {
		if (!p.alive) continue;
		p.age += dt;
		const k = p.age / p.life;
		if (k >= 1) { p.alive = false; p.sprite.visible = false; continue; }
		p.vel.x += (Math.random() - 0.5) * 0.12 * dt;
		p.sprite.position.addScaledVector(p.vel, dt);
		p.sprite.scale.setScalar(p.size0 + k * p.grow);
		p.sprite.material.rotation += p.spin * dt;
		p.sprite.material.opacity = Math.min(k / 0.12, 1) * (1 - k) * 0.5;
	}
}

// ---- Cara ----------------------------------------------------------------

// Beso (labios en piquito, boca cerrada): el puro se acerca y echa humo.
function kissStart(event) { kissing = true; }

// Fin del beso: el puro se aleja de la boca.
function kissEnd(event) { kissing = false; }

// Si se pierde la cara, el puro vuelve a su sitio.
function faceLost(event) { kissing = false; }
